import dao.*;import model.*;import util.*;
import java.sql.*;import java.math.BigDecimal;import java.time.LocalDate;import java.nio.file.*;import java.util.*;

/** Valores conhecidos em período futuro exclusivo; nunca usa a base principal. */
public final class RelatoriosFinanceiros {
    private static int cenarios;private static Cliente cliente;private static Produto produto;private static Usuario admin;private static final RelatorioDAO dao=new RelatorioDAO();
    private static final LocalDate INICIO=LocalDate.of(2031,2,1),FIM=LocalDate.of(2031,2,2);
    public static void main(String[] args)throws Exception {
        exigir(texto("SELECT current_database()").equals("obotbarato_test"),"Base isolada obrigatória.");admin=new UsuarioDAO().autenticar("admin","admin123");Sessao.iniciar(admin);produto=produto("Produto Relatório Histórico",50);Produto limite=produto("Estoque no mínimo Relatório",5),zerado=produto("Estoque zerado Relatório",0);
        String email="relatorio"+UUID.randomUUID().toString().substring(0,8)+"@teste.local";ClienteLojaDAO cad=new ClienteLojaDAO();exigir(cad.cadastrar("Cliente Relatório",null,email,"11999990000","Rua Relatórios, 100","senha12345")==null,"Cadastro falhou.");cliente=cad.autenticar(email,"senha12345");
        Sessao.encerrar();negar(()->dao.consultar(INICIO,FIM),SQLException.class);Sessao.iniciarCliente(cliente);negar(()->dao.consultar(INICIO,FIM),SQLException.class);Sessao.iniciar(admin);Usuario vendedor=new UsuarioDAO().autenticar("vendedor","vendedor123");Sessao.iniciar(vendedor);dao.consultar(INICIO,FIM);Sessao.iniciar(admin);ok("Somente equipe ativa consulta relatórios; cliente e ausência de sessão recusados");
        negar(()->dao.consultar(FIM,INICIO),IllegalArgumentException.class);negar(()->dao.consultar(null,FIM),IllegalArgumentException.class);ok("Período invertido e datas ausentes recusados");
        new CupomDAO().salvar(0,"RELATO2031",new BigDecimal("10"),LocalDate.now().minusDays(1),LocalDate.now().plusDays(1),true);
        Sessao.iniciarCliente(cliente);var oferta=new CupomDAO().consultar("RELATO2031");int pix=compra("pix",2,oferta),credito=compra("credito",1,null),pendente=compra("boleto",1,null),cancelado=compra("pix",1,null),fora=compra("credito",1,null);
        new GestaoPedidoDAO().cancelar(cancelado,"Cancelamento para testar o relatório");
        data(pix,"2031-02-01 00:00:00");data(credito,"2031-02-02 23:59:59.999");data(pendente,"2031-02-02 12:00:00");data(cancelado,"2031-02-02 13:00:00");data(fora,"2031-02-03 00:00:00");
        Sessao.iniciar(admin);long antes=numero("SELECT COUNT(*) FROM pedidos"),movimentos=numero("SELECT COUNT(*) FROM movimentos_estoque");var r=dao.consultar(INICIO,FIM);
        dinheiro(r.faturamento(),"262.00");exigir(r.confirmados()==2 && r.pendentes()==1 && r.cancelados()==1 && r.pedidos().size()==4,"Contagens incorretas.");dinheiro(r.ticket(),"131.00");exigir(r.quantidadeStatus("aberto")==3 && r.quantidadeStatus("cancelado")==1,"Status incorreto.");ok("Faturamento líquido R$ 262, duas vendas, ticket R$ 131; boleto e cancelado separados");
        var dia=r.vendas().get(0);dinheiro(dia.bruto(),"200.00");dinheiro(dia.cupom(),"20.00");dinheiro(dia.pagamento(),"18.00");dinheiro(dia.liquido(),"162.00");exigir(r.vendas().size()==2 && r.vendas().get(1).data().equals(FIM),"Fim do dia não incluído.");dinheiro(dao.consultar(INICIO,INICIO).faturamento(),"162.00");ok("Datas inclusivas, próximo dia excluído e descontos do cupom/PIX discriminados sem arredondamento incorreto");
        var ranking=r.ranking().stream().filter(v->v.id()==produto.getId()).findFirst().orElseThrow();exigir(ranking.quantidade()==3,"Ranking incluiu pendente/cancelado/fora do período.");dinheiro(ranking.bruto(),"300.00");new ProdutoDAO().excluir(produto.getId());exigir(dao.consultar(INICIO,FIM).ranking().stream().anyMatch(v->v.id()==produto.getId()),"Desativar produto apagou receita histórica.");ok("Ranking do mesmo período: três unidades e R$ 300 bruto; produto desativado preserva histórico");
        exigir(r.estoque().stream().anyMatch(e->e.id()==limite.getId()) && r.estoque().stream().anyMatch(e->e.id()==zerado.getId()),"Limite/zerado ausentes.");new ProdutoDAO().excluir(limite.getId());var vazio=dao.consultar(LocalDate.of(2034,1,1),LocalDate.of(2034,1,1));exigir(vazio.vendas().isEmpty() && vazio.ranking().isEmpty() && vazio.pedidos().isEmpty() && vazio.confirmados()==0 && vazio.ticket().signum()==0 && vazio.faturamento().signum()==0 && vazio.estoque().stream().anyMatch(e->e.id()==zerado.getId()) && vazio.estoque().stream().noneMatch(e->e.id()==limite.getId()),"Período vazio/estoque atual incorreto.");ok("Período vazio zera vendas; estoque crítico inclui limite/zerado ativos e independe do período");
        new CompraDAO().confirmarPagamento(pendente);r=dao.consultar(INICIO,FIM);dinheiro(r.faturamento(),"362.00");dinheiro(r.ticket(),"120.67");exigir(r.confirmados()==3 && r.pendentes()==0 && numero("SELECT COUNT(*) FROM pedidos")==antes && numero("SELECT COUNT(*) FROM movimentos_estoque")==movimentos,"Confirmação/consulta alterou estoque ou duplicou pedido.");ok("Boleto confirmado entra pela data da criação; ticket arredondado e consultas sem alteração de pedidos/estoque");
        Path pasta=Files.createTempDirectory(Path.of(".local"),"csv-teste-");Path arquivo=pasta.resolve("relatorio.csv");
        List<Object[]> linhas=new ArrayList<>();for(var v:r.vendas())linhas.add(new Object[]{v.data(),v.pedidos(),v.bruto(),v.cupom(),v.pagamento(),v.liquido()});ExportarCsv.salvar(arquivo,List.of("Data","Vendas","Bruto","Cupom","Pagamento","Líquido"),linhas);String csv=Files.readString(arquivo);exigir(csv.charAt(0)=='\ufeff' && csv.contains("\"01/02/2031\";\"1\";\"200,00\";\"20,00\";\"18,00\";\"162,00\"") && csv.contains("Líquido"),"CSV não corresponde ao snapshot/formato brasileiro.");ok("CSV UTF-8/BOM, datas brasileiras, vírgula decimal e totais iguais aos exibidos");
        ExportarCsv.salvar(arquivo,List.of("Nome","Valor"),List.<Object[]>of(new Object[]{"A; \"B\"\nC",new BigDecimal("12.34")},new Object[]{" =1+2",-5},new Object[]{"@SUM(1)",0},new Object[]{"\tformula",0}));csv=Files.readString(arquivo);exigir(csv.contains("\"A; \"\"B\"\"\nC\";\"12,34\"") && csv.contains("\"' =1+2\";\"-5\"") && csv.contains("'@SUM(1)") && csv.contains("'\tformula"),"Escapes ou proteção de fórmula incorretos.");negar(()->ExportarCsv.salvar(pasta.resolve("ausente/relatorio.csv"),List.of("Teste"),List.of()),java.io.IOException.class);exigir(Files.readString(arquivo).equals(csv),"Falha alterou arquivo anterior.");ok("Aspas, separadores e quebras de linha preservados; fórmulas neutralizadas e falha não altera arquivo anterior");
        Files.delete(arquivo);Files.delete(pasta);System.out.println("APROVADO: "+cenarios+" cenários de relatórios e CSV em PostgreSQL real.");
    }
    private static Produto produto(String nome,int saldo)throws Exception{Produto p=new Produto();p.setNome(nome);p.setPreco(new BigDecimal("100.00"));p.setIdCategoria(new CategoriaDAO().listar(false).get(0).id());p.setAtivo(true);p.setEstoqueInicial(saldo);new ProdutoDAO().salvar(p);return p;}
    private static int compra(String metodo,int quantidade,CupomDAO.Cupom cupom)throws SQLException{ItemPedido i=new ItemPedido();i.setIdProduto(produto.getId());i.setQuantidade(quantidade);i.setPrecoUnitario(produto.getPrecoDecimal());return new CompraDAO().confirmar(cliente.getId(),List.of(i),metodo,cliente.getNome(),cliente.getTelefone(),cliente.getEndereco(),UUID.randomUUID(),cupom==null?null:cupom.codigo(),cupom==null?null:cupom.percentual()).id();}
    private static void data(int id,String data)throws SQLException{try(Connection c=ConexaoBanco.getConexao();PreparedStatement p=c.prepareStatement("UPDATE pedidos SET data_pedido=? WHERE id=?")){p.setTimestamp(1,Timestamp.valueOf(data));p.setInt(2,id);p.executeUpdate();}}
    private static String texto(String sql)throws SQLException{try(Connection c=ConexaoBanco.getConexao();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){r.next();return r.getString(1);}}
    private static long numero(String sql)throws SQLException{return Long.parseLong(texto(sql));}
    private static void dinheiro(BigDecimal v,String esperado){exigir(v.compareTo(new BigDecimal(esperado))==0,"Valor incorreto: "+v+", esperado "+esperado);}
    @FunctionalInterface private interface Operacao{void executar()throws Exception;}
    private static void negar(Operacao o,Class<? extends Throwable> tipo)throws Exception{try{o.executar();}catch(Throwable e){if(tipo.isInstance(e))return;throw e;}throw new AssertionError("Operação indevida aceita.");}
    private static void exigir(boolean b,String s){if(!b)throw new AssertionError(s);}private static void ok(String s){cenarios++;System.out.println("OK "+cenarios+": "+s);}
}
